import{_ as t,o,c as n,ah as a}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"Part 1: The Dazzling Widow","description":"","frontmatter":{},"headers":[],"relativePath":"en/drehbuch/teil-1-die-schillernde-witwe.md","filePath":"en/drehbuch/teil-1-die-schillernde-witwe.md"}'),s={name:"en/drehbuch/teil-1-die-schillernde-witwe.md"};function r(i,e,h,l,c,d){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="part-1-the-dazzling-widow" tabindex="-1">Part 1: The Dazzling Widow <a class="header-anchor" href="#part-1-the-dazzling-widow" aria-label="Permalink to &quot;Part 1: The Dazzling Widow&quot;">​</a></h1><p><strong>Working Title:</strong> <em>From the Glow of Silence</em></p><p><strong>Cast:</strong> Birgit Minichmayr (Heidi Horten), August Diehl (The Young Helmut - in flashbacks), Oliver Masucci (The Curator/Chronicler).</p><hr><h2 id="scene-1-the-archive-of-the-smile" tabindex="-1">Scene 1: The Archive of the Smile <a class="header-anchor" href="#scene-1-the-archive-of-the-smile" aria-label="Permalink to &quot;Scene 1: The Archive of the Smile&quot;">​</a></h2><p><strong>Location:</strong> A state-of-the-art, air-conditioned depot near Klagenfurt. <strong>Time:</strong> Present day.</p><p>White gloves sit on polished tables everywhere. The camera glides over endless rows of jewelry boxes. Heidi (Birgit Minichmayr) enters the frame. She wears a simple but priceless silk dress. She opens one box after another.</p><p><strong>HEIDI</strong> (quietly, almost tenderly) This is not just jewelry. These are preserved moments. Helmut always said: &quot;Heidi, gold doesn&#39;t cry.&quot; He was right. It just continues to shine, no matter what happens outside.</p><p>She takes out a necklace; the pearls shimmer in the artificial light.</p><p><strong>HEIDI (Cont&#39;d)</strong> See this pearl? It&#39;s a dot. A small, white dot in an infinite balance sheet. If you have enough of them, you don&#39;t see the image anymore. You only see the light. That is my pointillism.</p><hr><h2 id="scene-2-the-pearl-inventory-tango" tabindex="-1">Scene 2: The Pearl Inventory Tango <a class="header-anchor" href="#scene-2-the-pearl-inventory-tango" aria-label="Permalink to &quot;Scene 2: The Pearl Inventory Tango&quot;">​</a></h2><p><strong>Location:</strong> The large mirrored hall in the palace. <strong>Time:</strong> A sleepless night.</p><p>Heidi spreads thousands of pearls on a huge black velvet cloth. She begins to sort them with silver tweezers. The rhythm of her movements becomes almost dance-like. In the background, a distorted version of a waltz plays quietly.</p><p><strong>HEIDI</strong> (to an imaginary person) One for the foundation. One for the art. Three for the silence. And one... for eternity.</p><p>The Curator (Oliver Masucci) watches her from the shadows.</p><p><strong>CURATOR</strong> Madame, the list of donation requests has grown. Politics is knocking. They want... rain again.</p><p><strong>HEIDI</strong> (without looking up) Then we give them rain, Curator. But only in drops. Piece by piece. Like these pearls. If you give everything at once, they drown. If you split it, gratitude grows.</p><hr><h2 id="scene-3-the-silence-of-the-yachts" tabindex="-1">Scene 3: The Silence of the Yachts <a class="header-anchor" href="#scene-3-the-silence-of-the-yachts" aria-label="Permalink to &quot;Scene 3: The Silence of the Yachts&quot;">​</a></h2><p><strong>Location:</strong> Deck of the <em>Carinthia VII</em>, off the coast of Nice. <strong>Time:</strong> Sunset.</p><p>The camera shows the massive dimensions of the yacht. It is so quiet that you only hear the gentle hum of the generators. Heidi sits at the stern, staring at the wake.</p><p><strong>HEIDI</strong> Helmut loved the sea. He said water has no memory. You can draw a trail, and seconds later it&#39;s gone. That is the freedom of money. It erases the traces of its own creation.</p><p>A steward serves champagne in crystal glasses so thin they seem like they would break just by looking at them.</p><p><strong>HEIDI (Cont&#39;d)</strong> Do you know what the problem with history is? It&#39;s too loud. It gathers dust. Wealth, on the other hand, is clinically clean. It smells of nothing. Except for tomorrow.</p><hr><h2 id="scene-4-the-heidi-gala-–-the-staging-of-nothingness" tabindex="-1">Scene 4: The Heidi Gala – The Staging of Nothingness <a class="header-anchor" href="#scene-4-the-heidi-gala-–-the-staging-of-nothingness" aria-label="Permalink to &quot;Scene 4: The Heidi Gala – The Staging of Nothingness&quot;">​</a></h2><p><strong>Location:</strong> A festively decorated hall, full of flowers bred to last exactly three hours. <strong>Time:</strong> An evening of &quot;High Society.&quot;</p><p>Birgit Minichmayr shines in a scene where she greets hundreds of guests without saying a single real word. It is a choreography of nodding and implied hugs.</p><p><strong>CHRONICLER (Masucci, Off-voice)</strong> She called it charity. The press called it generosity. We call it the perfect distraction. Every donated painting, every funded school was one more brushstroke in a portrait that overpainted the past.</p><p>Heidi stands at the microphone. The hall falls silent.</p><p><strong>HEIDI</strong> We are here to celebrate beauty. For beauty needs no explanation. It is simply there. Like the legacy we manage. We do not ask the question: &quot;From where?&quot; We ask the question: &quot;To where?&quot; And the answer is always: Into the future.</p><hr><h2 id="scene-5-the-archive-of-emptiness" tabindex="-1">Scene 5: The Archive of Emptiness <a class="header-anchor" href="#scene-5-the-archive-of-emptiness" aria-label="Permalink to &quot;Scene 5: The Archive of Emptiness&quot;">​</a></h2><p><strong>Location:</strong> A small, dark room behind the gallery. <strong>Time:</strong> Late at night.</p><p>Heidi looks at an old black-and-white photo of Helmut in front of his first department store. Her facial expression changes from nostalgia to a cold, almost mask-like determination.</p><p><strong>HEIDI</strong> (whispering to the photo) I&#39;ve kept it clean, Helmut. No one sees the dust anymore. Only the glow.</p><p>She turns off the light. Only the necklace in her hand continues to glow for a moment before everything goes black.</p><hr><h2 id="scene-6-the-pointillism-of-power" tabindex="-1">Scene 6: The Pointillism of Power <a class="header-anchor" href="#scene-6-the-pointillism-of-power" aria-label="Permalink to &quot;Scene 6: The Pointillism of Power&quot;">​</a></h2><p><strong>Location:</strong> A confidential meeting in the winter garden. <strong>Time:</strong> A cold January morning.</p><p>Heidi meets with a high representative of the &quot;Friends of the Arts&quot; (a code word for political masterminds).</p><p><strong>REPRESENTATIVE</strong> The elections are coming up, Madame. The people are... restless. They are asking questions about the origin of the large fortunes.</p><p><strong>HEIDI</strong> Then we must make the dots smaller. When you are close, you only see the chaos. When you step far away, you see a masterpiece. We must ensure that everyone stands far enough away.</p><p>She pours a bag of tiny diamonds onto the table. They sparkle like stars.</p><p><strong>HEIDI (Cont&#39;d)</strong> Here. This is my contribution to political stability. Distribute them well. But never call it &quot;money.&quot; Call it &quot;vision.&quot;</p><hr><h2 id="scene-7-the-shadows-of-the-carinthia" tabindex="-1">Scene 7: The Shadows of the <em>Carinthia</em> <a class="header-anchor" href="#scene-7-the-shadows-of-the-carinthia" aria-label="Permalink to &quot;Scene 7: The Shadows of the *Carinthia*&quot;">​</a></h2><p><strong>Location:</strong> In the belly of the yacht, near the engine rooms. <strong>Time:</strong> Night.</p><p>A stark contrast to the deck above. Here it is loud, hot, and oily. The Chronicler (Masucci) leads us through the &quot;entrails&quot; of luxury.</p><p><strong>CHRONICLER</strong> Down here is where the energy is generated that cools the ice above. It&#39;s like with the Horten fortune. Above there are smiles, below there is work. And deep in the foundation... there lies the scrap of history. The remains of the department stores that Helmut didn&#39;t &quot;buy,&quot; but &quot;took over.&quot;</p><p>He points to an old, rusted sewing machine forgotten in a corner. It bears the logo of the <em>Alsberg Brothers</em>.</p><hr><h2 id="scene-8-the-final-touch" tabindex="-1">Scene 8: The Final Touch <a class="header-anchor" href="#scene-8-the-final-touch" aria-label="Permalink to &quot;Scene 8: The Final Touch&quot;">​</a></h2><p><strong>Location:</strong> Heidi&#39;s bedroom. <strong>Time:</strong> Just before sunrise.</p><p>Heidi prepares for the day. She applies her makeup herself. Every brushstroke is precise.</p><p><strong>HEIDI</strong> (to the mirror) A little white under the eyes to hide the weariness of the ancestors. A little red on the lips to cover the coldness of the contracts. And gold... gold everywhere to blind the questions.</p><p>She steps to the window and looks out over Lake Wörthersee. The lake is smooth as a mirror.</p><p><strong>HEIDI (Cont&#39;d)</strong> Today will be a good day. No one will ask. Everyone will thank.</p><p><strong>FADE OUT.</strong></p>',60)])])}const u=t(s,[["render",r]]);export{p as __pageData,u as default};
